struct NestedIterator{st:Vec<NestedInteger>}impl NestedIterator{fn new(a:Vec<NestedInteger>)->Self{let mut st=a;st.reverse();Self{st}}fn prep(&mut self){loop{let expand=matches!(self.st.last(),Some(NestedInteger::List(_)));if !expand{break}if let Some(NestedInteger::List(mut v))=self.st.pop(){v.reverse();self.st.extend(v);}}}fn next(&mut self)->i32{self.prep();match self.st.pop().unwrap(){NestedInteger::Int(x)=>x,_=>unreachable!()}}fn has_next(&mut self)->bool{self.prep();!self.st.is_empty()}}
